<?php
namespace Modules\Academy\Services;
use Core\database\DB;use RuntimeException;
class AcademyTermTestService{
public function seed(int$actor):array{$pdo=db();$courses=$pdo->query("SELECT c.*,b.user_id branch_user_id FROM academy_branch_courses c JOIN academy_branches b ON b.branch_id=c.branch_id WHERE c.deleted_at IS NULL AND b.deleted_at IS NULL ORDER BY c.course_id")->fetchAll();if(!$courses)throw new RuntimeException('ابتدا تست دوره‌ها را اجرا کنید.');$curr=(int)($pdo->query('SELECT currency_id FROM financial_system_currency ORDER BY currency_id LIMIT 1')->fetchColumn()?:1);$term=$pdo->prepare("INSERT INTO academy_branch_course_terms(course_id,start_date,end_date,session_count,session_period,price,currency_id,status,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?)");$tr=$pdo->prepare("INSERT INTO translations(table_name,table_id,field,locale,value,version,created_by,updated_by) VALUES('academy_branch_course_terms',?,?,?,?,1,?,?)");$booking=$pdo->prepare("INSERT INTO academy_branch_bookings(type,status,requested_date,created_by,updated_by) VALUES('group-class',?,?,?,?)");$session=$pdo->prepare('INSERT INTO academy_branch_course_term_sessions(term_id,booking_id,classroom_id,teacher_id,created_by,updated_by) VALUES(?,?,?,?,?,?)');$enroll=$pdo->prepare("INSERT INTO academy_branch_course_term_enrollments(term_id,member_id,type,status,joined_at,created_by,updated_by) VALUES(?,?,?,'active',NOW(),?,?)");$att=$pdo->prepare('INSERT INTO academy_branch_course_term_session_attendances(session_id,term_enrollment_id,member_id,status,created_by,updated_by) VALUES(?,?,?,?,?,?)');$invoice=$pdo->prepare("INSERT INTO academy_branch_course_term_invoices(term_id,payable_amount,currency_id,status,due_date,created_by,updated_by) VALUES(?,?,?,'draft',?,?,?)");$install=$pdo->prepare("INSERT INTO academy_branch_course_term_invoice_installments(invoice_id,installment_number,amount,due_date,status,created_by,updated_by) VALUES(?,?,?,?,'pending',?,?)");$created=$sessions=$attendance=0;foreach($courses as$ci=>$c){$count=1+(($ci*17)%50);$room=(int)($pdo->query('SELECT classroom_id FROM academy_branch_classrooms WHERE branch_id='.(int)$c['branch_id'].' AND deleted_at IS NULL ORDER BY classroom_id LIMIT 1')->fetchColumn()?:0);if(!$room)continue;$teachers=$this->people((int)$c['branch_id'],'teacher',(int)$c['lesson_id'],max(1,(int)$c['teacher_capacity']));$students=$this->people((int)$c['branch_id'],'student',0,min(3,max(1,(int)$c['student_capacity'])));for($i=1;$i<=$count;$i++){$start=date('Y-m-d',strtotime('-'.(($i+$ci)%540).' days'));$sessionCount=4+(($i+$ci)%5);$end=date('Y-m-d',strtotime($start.' +'.(7*($sessionCount-1)).' days'));$status=strtotime($end)<time()?'finished':(strtotime($start)<=time()?'ongoing':'open');$term->execute([(int)$c['course_id'],$start,$end,$sessionCount,'week',1000000+(($i+$ci)%20)*250000,$curr,$status,$actor,$actor]);$tid=(int)$pdo->lastInsertId();$marker='test-term-c'.(int)$c['course_id'].'-'.$i;foreach(['code'=>$marker,'title'=>'ترم '.$i.' دوره '.(int)$c['course_id'],'summary'=>'ترم آزمایشی دوره شعبه','description'=>'این ترم توسط تست ترم‌ها، جلسات و حضور و غیاب ایجاد شده است.']as$field=>$value)$tr->execute([$tid,$field,'fa',$value,$actor,$actor]);$enrollmentRows=[];foreach(array_merge(array_map(fn($x)=>[$x,'teacher'],$teachers),array_map(fn($x)=>[$x,'student'],$students))as[$mid,$type]){$enroll->execute([$tid,$mid,$type,$actor,$actor]);$enrollmentRows[]=[(int)$pdo->lastInsertId(),$mid,$type];}$amount=1000000+(($i+$ci)%20)*250000;$invoice->execute([$tid,$amount,$curr,$start,$actor,$actor]);$iid=(int)$pdo->lastInsertId();$parts=1+(($i+$ci)%4);for($n=1;$n<=$parts;$n++)$install->execute([$iid,$n,$n===$parts?$amount-floor($amount/$parts)*($parts-1):floor($amount/$parts),date('Y-m-d',strtotime($start.' +'.($n-1).' month')),$actor,$actor]);for($s=0;$s<$sessionCount;$s++){$date=date('Y-m-d',strtotime($start.' +'.(7*$s).' days'));$booking->execute([strtotime($date)<=time()?'completed':'approved',$date,$actor,$actor]);$bid=(int)$pdo->lastInsertId();$teacherId=$teachers?$teachers[$s%count($teachers)]:null;$session->execute([$tid,$bid,$room,$teacherId,$actor,$actor]);$sid=(int)$pdo->lastInsertId();$sessions++;if(strtotime($date)<=time())foreach($enrollmentRows as[$eid,$mid,$type]){$statuses=['present','present','present','late','absent'];$att->execute([$sid,$eid,$mid,$statuses[($mid+$s+$i)%5],$actor,$actor]);$attendance++;}}$created++;}if(($ci+1)%50===0){session_write_close();set_time_limit(120);}}return compact('created','sessions','attendance');}
public function delete():array{$pdo=db();$ids=$pdo->query("SELECT DISTINCT table_id FROM translations WHERE table_name='academy_branch_course_terms' AND field='code' AND value LIKE 'test-term-c%'")->fetchAll(\PDO::FETCH_COLUMN);if(!$ids)return['deleted'=>0];$deleted=0;foreach(array_chunk($ids,500)as$chunk){$in=implode(',',array_map('intval',$chunk));$sessionIds=$pdo->query("SELECT term_session_id FROM academy_branch_course_term_sessions WHERE term_id IN ($in)")->fetchAll(\PDO::FETCH_COLUMN);$bookingIds=$pdo->query("SELECT booking_id FROM academy_branch_course_term_sessions WHERE term_id IN ($in)")->fetchAll(\PDO::FETCH_COLUMN);$invoiceIds=$pdo->query("SELECT term_invoice_id FROM academy_branch_course_term_invoices WHERE term_id IN ($in)")->fetchAll(\PDO::FETCH_COLUMN);if($sessionIds)$pdo->exec('DELETE FROM academy_branch_course_term_session_attendances WHERE session_id IN ('.implode(',',array_map('intval',$sessionIds)).')');if($invoiceIds)$pdo->exec('DELETE FROM academy_branch_course_term_invoice_installments WHERE invoice_id IN ('.implode(',',array_map('intval',$invoiceIds)).')');$pdo->exec("DELETE FROM academy_branch_course_term_invoices WHERE term_id IN ($in)");$pdo->exec("DELETE FROM academy_branch_course_term_enrollments WHERE term_id IN ($in)");$pdo->exec("DELETE FROM academy_branch_course_term_sessions WHERE term_id IN ($in)");if($bookingIds)$pdo->exec('DELETE FROM academy_branch_bookings WHERE booking_id IN ('.implode(',',array_map('intval',$bookingIds)).')');$pdo->exec("DELETE FROM translations WHERE table_name='academy_branch_course_terms' AND table_id IN ($in)");$pdo->exec("DELETE FROM academy_branch_course_terms WHERE term_id IN ($in)");$deleted+=count($chunk);}return compact('deleted');}
private function people(int$branch,string$type,int$lesson,int$limit):array{$pdo=db();if($type==='teacher')$sql="SELECT m.member_id FROM academy_branch_members m JOIN academy_branch_member_contracts c ON c.member_id=m.member_id AND c.type='teacher' AND c.deleted_at IS NULL JOIN user_lessons ul ON ul.user_lesson_id=c.user_lesson_id AND ul.lesson_id=$lesson AND ul.deleted_at IS NULL WHERE m.branch_id=$branch AND m.deleted_at IS NULL LIMIT $limit";else$sql="SELECT m.member_id FROM academy_branch_members m JOIN users u ON u.user_id=m.user_id WHERE m.branch_id=$branch AND m.deleted_at IS NULL AND u.username LIKE '%student_%' LIMIT $limit";$people=array_map('intval',$pdo->query($sql)->fetchAll(\PDO::FETCH_COLUMN));if(!$people)throw new RuntimeException($type==='teacher'?'برای ساخت ترم آزمایشی، مدرس واجدشرایط این درس در شعبه وجود ندارد.':'برای ساخت ترم آزمایشی، حداقل یک هنرجو در شعبه لازم است.');return$people;}}
